var toHex = function(num) {
    if (num === 0) return "0";
    let n = num < 0 ? num + Math.pow(2, 32) : num;
    const digits = "0123456789abcdef";
    let res = "";
    while (n > 0) {
        res = digits[n % 16] + res;
        n = Math.floor(n / 16);
    }
    return res;
};

