class Solution {
    public String toHex(int num) {
        if (num == 0) return "0";
        char[] digits = "0123456789abcdef".toCharArray();
        StringBuilder sb = new StringBuilder();
        while (num != 0 && sb.length() < 8) {
            sb.append(digits[num & 15]);
            num >>>= 4;
        }
        return sb.reverse().toString();
    }
}

